"""Self-contained, zero-dependency offline visual investigative console."""
from __future__ import annotations
import json

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>OpenInference Lab — Evidence Console</title>
<style>
:root{--bg:#09131d;--panel:#111f2a;--panel2:#142431;--panel3:#0d1a24;--line:#2a3c49;--text:#e7f1f5;--sub:#91a6b4;--teal:#52d5c2;--blue:#6db6ef;--amber:#f8c875;--red:#fd8486;--green:#8ddab7}
*{box-sizing:border-box}body{margin:0;color:var(--text);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;background:radial-gradient(circle at 74% 0%,#123246 0%,transparent 34%),var(--bg)}
header{height:auto;min-height:83px;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 30px;border-bottom:1px solid var(--line);background:#0a1721d9}
.brand{display:flex;align-items:center;gap:13px}.logo{width:39px;height:39px;border:1px solid #397b87;display:grid;place-items:center;border-radius:11px;background:#103947;color:var(--teal);font-size:23px;font-weight:700}.brand h1{font-size:18px;letter-spacing:.01em;margin:0}.brand p{font-size:11px;letter-spacing:.12em;color:var(--sub);margin:2px 0 0;text-transform:uppercase}
.header-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.tag{border:1px solid #37616a;color:var(--teal);background:#15303a;padding:5px 9px;border-radius:7px;font-size:11px;letter-spacing:.08em;font-weight:700}.select,button{background:var(--panel2);border:1px solid #354b59;border-radius:7px;color:var(--text);padding:9px 12px;font:inherit;cursor:pointer}button:hover,.select:hover{border-color:var(--teal)}select{min-width:150px}button{font-size:12px}
main{padding:24px 28px 35px;max-width:1800px;margin:auto}.intro{display:flex;justify-content:space-between;align-items:end;gap:16px}.eyebrow{font-size:10px;letter-spacing:.16em;font-weight:800;text-transform:uppercase;color:var(--teal)}h2{font-size:25px;font-weight:680;letter-spacing:-.03em;margin:6px 0}p{margin:5px 0}.lead{color:var(--sub);font-size:13px;max-width:800px}.risk{color:var(--amber);font-size:11px;max-width:390px;text-align:right}
.kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin:23px 0}.kpi{background:linear-gradient(155deg,#172c39,#101e29);border:1px solid var(--line);border-radius:11px;padding:16px 18px;min-height:105px}.kpi label{display:block;color:var(--sub);font-size:10px;letter-spacing:.12em;text-transform:uppercase;font-weight:750}.num{font-size:29px;font-weight:720;letter-spacing:-.04em;margin-top:4px;line-height:1.3}.kpi small{color:var(--sub);font-size:11px}
.layout{display:grid;grid-template-columns:minmax(240px,1.04fr) minmax(420px,1.8fr) minmax(310px,1.23fr);gap:14px;align-items:start}.pane{background:var(--panel);border:1px solid var(--line);border-radius:11px;overflow:hidden}.panelhead{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:16px 17px;border-bottom:1px solid var(--line)}.panelhead h3{font-size:13px;margin:0;font-weight:710}.panelhead small,.muted{color:var(--sub);font-size:11px}.panecontent{padding:15px}
.filter{width:100%;border-radius:8px;border:1px solid #344958;background:#0b1924;padding:10px;color:white;outline:none}.filter:focus{border-color:var(--teal)}.eventlist{max-height:650px;min-height:400px;overflow:auto}.event{display:flex;gap:10px;padding:13px 14px;cursor:pointer;border-bottom:1px solid #233543}.event:hover{background:#1a3040}.event.selected{background:#173543;box-shadow:inset 3px 0 var(--teal)}.mag{font-weight:730;font-size:17px;min-width:40px;color:var(--text)}.eventtext{min-width:0}.ename{font-weight:640;font-size:12px}.esub{font-size:10px;color:var(--sub);margin-top:4px}.pill{display:inline-block;border:1px solid #375668;border-radius:5px;font-size:9px;padding:2px 6px;margin-top:6px;letter-spacing:.04em;font-weight:780}.pill.MONITOR{color:var(--sub)}.pill.INVESTIGATE_PATTERN{color:var(--teal);border-color:#2f716c;background:#113b39}.pill.VERIFY_LARGE_RECORD{color:var(--amber);border-color:#736047}.pill.CHECK_DATA{color:var(--red);border-color:#835255;background:#3b202a}
.section{padding:15px 17px;border-bottom:1px solid var(--line)}.section:last-child{border-bottom:0}.section h4{font-size:11px;color:var(--sub);letter-spacing:.11em;text-transform:uppercase;margin:0 0 12px}.mapbox{border-radius:8px;background:radial-gradient(ellipse at 50% 50%,#1d3b48,#0d202b);height:300px;position:relative;overflow:hidden;border:1px solid #213c4a}.mapbox svg{width:100%;height:100%}.maplegend{display:flex;justify-content:space-between;margin-top:8px;color:var(--sub);font-size:10px}.detailtop{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.idtext{font:11px ui-monospace,Menlo,Consolas,monospace;color:var(--teal)}.detailtitle{font-size:17px;font-weight:690;line-height:1.35;margin:7px 0}.facts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.fact{border:1px solid #2b4653;background:#102631;border-radius:6px;padding:9px}.fact label{display:block;text-transform:uppercase;letter-spacing:.06em;color:var(--sub);font-size:9px}.fact strong{display:block;font-size:14px;font-weight:700;margin-top:3px}.reason{color:#d0e0e8;font-size:12px}.decision{padding:12px;background:#143344;border-left:3px solid var(--teal);border-radius:5px;margin:10px 0}.decision.warn{background:#332a2b;border-color:var(--red)}.decision strong{font-size:12px}.checks{margin:0;padding:0;list-style:none}.checks li{padding:7px 0;border-bottom:1px solid #293c49;color:#b8d3dc;font-size:11px}.checks li:last-child{border:0}.ok{color:var(--teal)}.bad{color:var(--red)}a{color:#86cce5;text-decoration:none}a:hover{text-decoration:underline}
.provenance{height:195px;width:100%;border:1px solid #29424f;border-radius:8px;background:#0a1c26}.footnote{font-size:10px;color:var(--sub);margin:10px 0 0;line-height:1.6}.timeline{display:flex;align-items:end;gap:6px;height:115px;padding:9px 3px 18px;border-bottom:1px solid var(--line)}.bar{flex:1;min-width:4px;border-radius:3px 3px 0 0;background:#356b78;cursor:pointer;position:relative;transition:background .1s}.bar:hover,.bar.active{background:var(--teal)}.bar:after{content:attr(data-mag);position:absolute;font-size:9px;color:#a7c0cd;left:50%;transform:translateX(-50%);top:-16px;opacity:0}.bar:hover:after,.bar.active:after{opacity:1}.meta{color:var(--sub);font-size:11px}.result-pass{color:var(--green)}.result-fail{color:var(--red)}.auditgrid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.auditcell{padding:10px;background:#0e2630;border:1px solid #2c4651;border-radius:7px}.auditcell strong{display:block;font-size:15px}.auditcell span{font-size:10px;color:var(--sub)}
footer{border-top:1px solid var(--line);padding:18px 28px;color:var(--sub);font-size:11px;max-width:1800px;margin:0 auto}.warning{color:#f7ca83}.snapshot{font:10px ui-monospace,Consolas,monospace;color:#86a6b4;word-break:break-all}
@media(max-width:1200px){.layout{grid-template-columns:1fr 1.5fr}.inspector{grid-column:1/-1}.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:750px){header{padding:15px}main{padding:15px}.intro{display:block}.risk{text-align:left;margin:10px 0}.layout{grid-template-columns:1fr}.inspector{grid-column:auto}.kpis{grid-template-columns:repeat(2,1fr)}.mapbox{height:240px}}
</style></head>
<body>
<header><div class="brand"><div class="logo">◇</div><div><h1>OPENINFERENCE <span style="color:var(--teal)">LAB</span></h1><p>Evidence &amp; Integrity Console / educational v0.1</p></div></div>
<div class="header-actions"><span class="tag">OFFLINE · SOURCE-TRACEABLE</span><select id="scenario" class="select" aria-label="Scenario"><option value="clean">01 / Baseline</option><option value="adversarial">02 / Adversarial</option></select><button id="export">Export audit JSON</button></div></header>
<main><div class="intro"><div><div class="eyebrow">An AI-native scientist's workbench</div><h2>From observations to defensible decisions.</h2><p class="lead">A complete micro-system: real public records → integrity gate → space/time inference → analyst decision → independent audit. Select a record to inspect its evidence chain.</p></div><div class="risk">Research education only. Not earthquake forecasting, safety advice, or an official USGS product.</div></div>
<div id="kpis" class="kpis"></div>
<div class="layout">
<section class="pane"><div class="panelhead"><h3>01 · Observations</h3><small id="samplelabel">public source records</small></div><div class="panecontent"><input id="filter" class="filter" placeholder="Search location, ID or decision…"></div><div id="events" class="eventlist"></div></section>
<div><section class="pane"><div class="panelhead"><h3>02 · Spatial evidence</h3><small>100 km / 24 hours rule</small></div><div class="section"><div class="mapbox"><svg id="map" viewBox="0 0 960 300" role="img" aria-label="World-coordinate location plot of earthquake records"></svg></div><div class="maplegend"><span>● reported USGS epicenters &nbsp; ━ nearby record relationships</span><span>Coordinates only · not a hazard map</span></div></div><div class="section"><h4>Event chronology · magnitude</h4><div id="timeline" class="timeline"></div><p class="footnote">Bars are events ordered by observation time. Click to inspect a source record. Larger magnitude does not imply higher data reliability.</p></div></section>
<section class="pane" style="margin-top:14px"><div class="panelhead"><h3>04 · Independent integrity audit</h3><span id="auditbadge" class="tag">VERIFIER</span></div><div class="section"><div id="auditfacts" class="auditgrid"></div><p class="footnote" id="auditnotes"></p></div><div class="section"><h4>Detected integrity exceptions</h4><ul class="checks" id="issues"></ul></div></section></div>
<section class="pane inspector"><div class="panelhead"><h3>03 · Decision inspector</h3><small>Every claim needs evidence</small></div><div id="detail"></div></section>
</div>
</main><footer><strong>Separation of duties:</strong> inference rules produce candidate findings; the independent verifier recomputes constraints and checks source hashes. Neither a passing test nor a model explanation establishes geophysical truth. <span class="warning">The adversarial scenario contains explicitly injected fictional corruptions.</span><br><span id="sourceinfo"></span></footer>
<script>
const REPORTS = __DATA__;
const byId=id=>document.getElementById(id), fmt=n=>typeof n==='number'?n.toLocaleString(undefined,{maximumFractionDigits:2}):String(n??'—');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let scenario='clean',selected=null;
const color=d=>d==='CHECK_DATA'?'#fd8486':d==='INVESTIGATE_PATTERN'?'#52d5c2':d==='VERIFY_LARGE_RECORD'?'#f8c875':'#6b899b';
const label=d=>({CHECK_DATA:'CHECK DATA',INVESTIGATE_PATTERN:'INVESTIGATE PATTERN',VERIFY_LARGE_RECORD:'VERIFY LARGE RECORD',MONITOR:'MONITOR'})[d]||d;
function render(){const r=REPORTS[scenario];if(!selected||!r.records.find(x=>x.id===selected))selected=r.records.find(x=>x.decision!=='MONITOR')?.id||r.records[0]?.id;
 const s=r.summary;byId('kpis').innerHTML=[['Records',s.records,'sourced observations'],['Pattern groups',s.clusters,'candidate neighborhoods'],['Analyst queue',s.review_queue,'not automatic interventions'],['Quarantined',s.quarantined,'blocked from inference'],['Independent audit',r.audit.status,r.audit.checks+' assertions']].map(([label,value,sub])=>`<div class="kpi"><label>${esc(label)}</label><div class="num" style="color:${value==='PASS'?'var(--green)':label==='Quarantined'&&value?'var(--red)':''}">${esc(value)}</div><small>${esc(sub)}</small></div>`).join('');
 byId('samplelabel').textContent=r.meta.sample_size+' selected records';byId('sourceinfo').innerHTML=`Source: <a href="${esc(r.meta.source_url)}" target="_blank" rel="noopener">USGS M4.5+ feed</a> · Frozen public snapshot, not live. Original feed contained ${r.meta.source_total_records} events. This demonstration intentionally uses only the first 15.`;
 drawEvents();drawMap();drawTimeline();drawDetail();drawAudit();}
function drawEvents(){const q=byId('filter').value.toLowerCase();const r=REPORTS[scenario];const filtered=r.records.filter(x=>(x.id+' '+x.place+' '+x.decision+' '+x.issues.join(' ')).toLowerCase().includes(q));
 byId('events').innerHTML=filtered.map(x=>`<div class="event ${x.id===selected?'selected':''}" data-id="${esc(x.id)}"><div class="mag">${fmt(x.mag)}</div><div class="eventtext"><div class="ename">${esc(x.place)}</div><div class="esub">${esc(x.id)} &nbsp;·&nbsp; ${esc(x.status)}</div><span class="pill ${x.decision}">${label(x.decision)}</span> ${x.injected_fixture?'<span class="pill CHECK_DATA">LAB INJECTION</span>':''}</div></div>`).join('')||'<p class="panecontent muted">No matching records.</p>';
 byId('events').querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>choose(x.dataset.id));}
function choose(id){selected=id;drawEvents();drawMap();drawTimeline();drawDetail();}
function xy(r){return [24+(r.lon+180)/360*912, 16+(90-r.lat)/180*268]}
function drawMap(){const r=REPORTS[scenario], items=r.records;let parts=[];
 for(let lat=-60;lat<=60;lat+=30){let y=16+(90-lat)/180*268;parts.push(`<path d="M24 ${y}H936" stroke="#2b4856" stroke-dasharray="3 7" stroke-width=".8"/>`)}
 for(let lon=-180;lon<=180;lon+=45){let x=24+(lon+180)/360*912;parts.push(`<path d="M${x} 16V284" stroke="#2b4856" stroke-dasharray="3 7" stroke-width=".8"/>`)}
 for(const e of r.edges){const a=items.find(x=>x.id===e.source),b=items.find(x=>x.id===e.target);if(!a||!b)continue;const p=xy(a),q=xy(b);parts.push(`<path d="M${p[0]} ${p[1]}L${q[0]} ${q[1]}" stroke="#4f9c9a" stroke-width="2.1" opacity=".73"/>`)}
 for(const e of items){if(!Number.isFinite(e.lat)||Math.abs(e.lat)>90||!Number.isFinite(e.lon)||Math.abs(e.lon)>180)continue;const p=xy(e),sel=e.id===selected,rad=sel?7:4.5;const c=color(e.decision);if(sel)parts.push(`<circle cx="${p[0]}" cy="${p[1]}" r="11" fill="${c}" opacity=".14"/>`);parts.push(`<circle data-id="${esc(e.id)}" cx="${p[0]}" cy="${p[1]}" r="${rad}" fill="${c}" stroke="#0c1d27" stroke-width="1.5" style="cursor:pointer"><title>${esc(e.place)} (M ${e.mag})</title></circle>`)}
 parts.push('<text x="30" y="291" font-size="10" fill="#7998a9">−180°</text><text x="870" y="291" font-size="10" fill="#7998a9">+180°</text>');byId('map').innerHTML=parts.join('');
 byId('map').querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>choose(x.getAttribute('data-id')));}
function drawTimeline(){const items=[...REPORTS[scenario].records].sort((a,b)=>a.time_ms-b.time_ms);byId('timeline').innerHTML=items.map(r=>`<div class="bar ${r.id===selected?'active':''}" data-id="${esc(r.id)}" data-mag="M ${fmt(r.mag)}" title="${esc(r.id)}" style="height:${Math.max(10,Math.max(0,(r.mag+2))/9.5*88)}px;background:${r.id===selected?color(r.decision):''}"></div>`).join('');byId('timeline').querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>choose(x.dataset.id));}
function drawDetail(){const r=REPORTS[scenario],x=r.records.find(y=>y.id===selected);if(!x)return;let cluster=r.clusters.find(g=>g.id===x.cluster_id),others=x.neighbor_ids.map(id=>r.records.find(y=>y.id===id)).filter(Boolean);
 const fact=(l,v)=>`<div class="fact"><label>${esc(l)}</label><strong>${esc(fmt(v))}</strong></div>`;
 const attrs=[['Magnitude',x.mag],['Depth, km',x.depth_km],['Latitude',x.lat],['Longitude',x.lon],['Status',x.status],['Quality heuristic',x.evidence_quality+' / 1.00']];
 byId('detail').innerHTML=`<div class="section"><div class="detailtop"><span class="idtext">${esc(x.id)}</span>${x.injected_fixture?'<span class="pill CHECK_DATA">INJECTED, NOT REAL DATA</span>':''}</div><div class="detailtitle">${esc(x.place)}</div><div class="meta">${new Date(x.time_ms).toLocaleString()} · Source network ${esc(x.net)}</div><div class="facts">${attrs.map(([l,v])=>fact(l,v)).join('')}</div>${x.source_url?`<a href="${esc(x.source_url)}" target="_blank" rel="noopener">Open original USGS event ↗</a>`:`<span class="bad">No public source: fabricated teaching fixture</span>`}<div class="snapshot">SHA256: ${esc(x.sha256)}</div></div>
 <div class="section"><h4>Evidence → inference → decision</h4><svg viewBox="0 0 320 172" class="provenance" aria-label="Provenance graph">${graph(x,others)}</svg><p class="footnote">Solid arrows indicate recorded dependency, not causal relationships. Inferences are gated on data integrity.</p></div>
 <div class="section"><h4>Decision and explanation</h4><div class="decision ${x.issues.length?'warn':''}"><strong>${esc(label(x.decision))}</strong><p class="reason">${esc(x.reason)}</p></div><p class="meta">Rule: <span class="idtext">${esc(x.rule)}</span>${cluster?' · Cluster: '+esc(cluster.id):''}</p></div>
 <div class="section"><h4>Traceability and model constraints</h4><ul class="checks">${(x.issues.length?x.issues.map(i=>`<li><span class="bad">✕</span> ${esc(i)}</li>`):['Valid schema and ranges','Frozen source fingerprint matches','No duplicate report detected'].map(t=>`<li><span class="ok">✓</span> ${esc(t)}</li>`)).join('')}</ul><p class="footnote">Evidence IDs: ${x.evidence_ids.map(id=>`<span class="idtext">${esc(id)}</span>`).join(', ')}. A claimed pattern is not automatically an aftershock sequence.</p></div>`;
}
function graph(x,others){const flagged=x.issues.length>0, c=color(x.decision), mid=others.length?`NEIGHBORS (${others.length})`:'THRESHOLD RULE';return `<defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0L6,3L0,6Z" fill="#7e9eaf"/></marker></defs><path d="M74 85H122 M205 85H245" fill="none" stroke="#7e9eaf" stroke-width="1.4" marker-end="url(#arrow)"/><rect x="7" y="51" width="88" height="66" rx="8" fill="#193648" stroke="#3c7788"/><text x="51" y="78" text-anchor="middle" fill="#9cdbec" font-size="10">FACTS</text><text x="51" y="94" text-anchor="middle" fill="#d0e9ee" font-size="9">${esc(x.id.slice(-8))}</text><rect x="119" y="51" width="108" height="66" rx="8" fill="${flagged?'#382730':'#173a40'}" stroke="${flagged?'#ab6667':'#4b958f'}"/><text x="173" y="75" text-anchor="middle" fill="#c1e9e8" font-size="10">${flagged?'INTEGRITY GATE':'INFERENCE'}</text><text x="173" y="91" text-anchor="middle" fill="#8caebf" font-size="8">${flagged?'QUARANTINE':esc(mid)}</text><rect x="244" y="51" width="70" height="66" rx="8" fill="#243541" stroke="${c}"/><text x="279" y="76" text-anchor="middle" fill="${c}" font-size="10">ACTION</text><text x="279" y="94" text-anchor="middle" fill="#c3d8e0" font-size="8">${flagged?'CHECK':'REVIEW / LOG'}</text><text x="160" y="151" text-anchor="middle" fill="#688fa2" font-size="9">Source ↦ claim ↦ human decision</text>`;}
function drawAudit(){const r=REPORTS[scenario],s=r.summary,a=r.audit;byId('auditbadge').textContent=a.status+' · '+a.checks+' CHECKS';byId('auditbadge').style.color=a.status==='PASS'?'var(--green)':'var(--red)';byId('auditfacts').innerHTML=[['Passed input records',s.passed],['Quarantined records',s.quarantined],['Integrity exceptions',s.issue_count],['Audit discrepancies',a.failures.length]].map(([name,val])=>`<div class="auditcell"><strong>${val}</strong><span>${esc(name)}</span></div>`).join('');byId('auditnotes').textContent=a.method+'; no geophysical ground truth or calibrated probability is claimed.';
 const bad=r.records.filter(x=>x.issues.length);byId('issues').innerHTML=bad.length?bad.map(x=>`<li><span class="bad">✕</span> <span class="idtext">${esc(x.id)}</span> · ${x.issues.map(esc).join(', ')}</li>`).join(''):'<li><span class="ok">✓</span> No issues found in this limited frozen snapshot.</li>';
 if(a.failures.length)byId('issues').innerHTML+=a.failures.map(x=>`<li class="bad">Independent audit: ${esc(x)}</li>`).join('');
}
byId('scenario').addEventListener('change',e=>{scenario=e.target.value;selected=null;byId('filter').value='';render()});byId('filter').addEventListener('input',drawEvents);
byId('export').addEventListener('click',()=>{const b=new Blob([JSON.stringify(REPORTS[scenario],null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='openinference_'+scenario+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});
render();
</script></body></html>'''


def render_html(reports):
    payload = json.dumps(reports, ensure_ascii=False, separators=(",", ":")).replace("<", "\\u003c")
    return HTML.replace("__DATA__", payload)
